8	const RESET = '\x1b[0m';
9	const BOLD = '\x1b[1m';
10	const DIM = '\x1b[38;5;102m';
11	const TEXT = '\x1b[38;5;145m';
12	const CYAN = '\x1b[36m';
13	const MAGENTA = '\x1b[35m';
