16	// API endpoint for skills search
17	const SEARCH_API_BASE = process.env.SKILLS_API_URL || 'https://skills.sh';
18	
19	function formatInstalls(count: number): string {
20	  if (!count || count <= 0) return '';
21	  if (count >= 1_000_000) return `${(count / 1_000_000).toFixed(1).replace(/\.0$/, '')}M installs`;
22	  if (count >= 1_000) return `${(count / 1_000).toFixed(1).replace(/\.0$/, '')}K installs`;
23	  return `${count} install${count === 1 ? '' : 's'}`;
24	}
