43	const GITHUB_OWNER_PATTERN = /^[a-z0-9](?:[a-z0-9-]{0,38})$/i;
44	
45	export function parseFindOptions(args: string[]): ParseFindOptionsResult {
46	  const queryParts: string[] = [];
47	  const options: FindOptions = {};
48	  const errors: string[] = [];
49	
50	  for (let i = 0; i < args.length; i++) {
51	    const arg = args[i];
52	    if (!arg) continue;
53	
54	    let ownerValue: string | undefined;
55	    if (arg === '--owner') {
56	      const value = args[i + 1];
57	      if (!value || value.startsWith('-')) {
58	        errors.push('--owner requires a GitHub owner');
59	        continue;
60	      }
61	      ownerValue = value;
62	      i++;
63	    } else if (arg.startsWith('--owner=')) {
64	      ownerValue = arg.slice('--owner='.length);
65	      if (!ownerValue) {
66	        errors.push('--owner requires a GitHub owner');
67	        continue;
68	      }
69	    } else {
70	      queryParts.push(arg);
71	      continue;
72	    }
73	
74	    const owner = ownerValue.trim().toLowerCase();
75	    if (!GITHUB_OWNER_PATTERN.test(owner)) {
76	      errors.push('--owner must be a valid GitHub owner');
77	      continue;
78	    }
79	    options.owner = owner;
80	  }
81	
82	  return { query: queryParts.join(' '), options, errors };
83	}
