85	// Search via API
86	export async function searchSkillsAPI(query: string, owner?: string): Promise<SearchSkill[]> {
87	  try {
88	    const params = new URLSearchParams({ q: query, limit: '10' });
89	    if (owner) params.set('owner', owner);
90	    const url = `${SEARCH_API_BASE}/api/search?${params.toString()}`;
91	    const res = await fetch(url);
92	
93	    if (!res.ok) return [];
94	
95	    const data = (await res.json()) as {
96	      skills: Array<{
97	        id: string;
98	        name: string;
99	        installs: number;
100	        source: string;
101	      }>;
102	    };
103	
104	    return data.skills
105	      .map((skill) => ({
106	        name: sanitizeMetadata(skill.name),
107	        slug: sanitizeMetadata(skill.id),
108	        source: sanitizeMetadata(skill.source || ''),
109	        installs: skill.installs,
110	      }))
111	      .sort((a, b) => (b.installs || 0) - (a.installs || 0));
112	  } catch {
113	    return [];
114	  }
115	}
