117	// ANSI escape codes for terminal control
118	const HIDE_CURSOR = '\x1b[?25l';
119	const SHOW_CURSOR = '\x1b[?25h';
120	const CLEAR_DOWN = '\x1b[J';
121	const MOVE_UP = (n: number) => `\x1b[${n}A`;
122	const MOVE_TO_COL = (n: number) => `\x1b[${n}G`;
123	
124	// Custom fzf-style search prompt using raw readline
125	async function runSearchPrompt(initialQuery = '', owner?: string): Promise<SearchSkill | null> {
126	  let results: SearchSkill[] = [];
127	  let selectedIndex = 0;
128	  let query = initialQuery;
129	  let loading = false;
130	  let debounceTimer: ReturnType<typeof setTimeout> | null = null;
131	  let lastRenderedLines = 0;
132	
133	  // Enable raw mode for keypress events
134	  if (process.stdin.isTTY) {
135	    process.stdin.setRawMode(true);
136	  }
137	
138	  // Setup readline for keypress events but don't let it echo
139	  readline.emitKeypressEvents(process.stdin);
140	
141	  // Resume stdin to start receiving events
142	  process.stdin.resume();
143	
144	  // Hide cursor during selection
145	  process.stdout.write(HIDE_CURSOR);
146	
147	  function render(): void {
148	    // Move cursor up to overwrite previous render
149	    if (lastRenderedLines > 0) {
150	      process.stdout.write(MOVE_UP(lastRenderedLines) + MOVE_TO_COL(1));
151	    }
152	
153	    // Clear from cursor to end of screen (removes ghost trails)
154	    process.stdout.write(CLEAR_DOWN);
155	
156	    const lines: string[] = [];
157	
158	    // Search input line with cursor
159	    const cursor = `${BOLD}_${RESET}`;
160	    lines.push(`${TEXT}Search skills:${RESET} ${query}${cursor}`);
161	    lines.push('');
162	
163	    // Results - keep showing existing results while loading new ones
164	    if (!query || query.length < 2) {
165	      lines.push(`${DIM}Start typing to search (min 2 chars)${RESET}`);
166	    } else if (results.length === 0 && loading) {
167	      lines.push(`${DIM}Searching…${RESET}`);
168	    } else if (results.length === 0) {
169	      lines.push(`${DIM}No skills found${RESET}`);
170	    } else {
171	      const maxVisible = 8;
172	      const visible = results.slice(0, maxVisible);
173	
174	      for (let i = 0; i < visible.length; i++) {
175	        const skill = visible[i]!;
176	        const isSelected = i === selectedIndex;
177	        const arrow = isSelected ? `${BOLD}>${RESET}` : ' ';
178	        const name = isSelected ? `${BOLD}${skill.name}${RESET}` : `${TEXT}${skill.name}${RESET}`;
179	        const source = skill.source ? ` ${DIM}${skill.source}${RESET}` : '';
180	        const installs = formatInstalls(skill.installs);
181	        const installsBadge = installs ? ` ${CYAN}${installs}${RESET}` : '';
182	        const loadingIndicator = loading && i === 0 ? ` ${DIM}…${RESET}` : '';
183	
184	        lines.push(`  ${arrow} ${name}${source}${installsBadge}${loadingIndicator}`);
185	      }
186	    }
187	
188	    lines.push('');
189	    lines.push(`${DIM}up/down navigate | enter select | esc cancel${RESET}`);
190	
191	    // Write each line
192	    for (const line of lines) {
193	      process.stdout.write(line + '\n');
194	    }
195	
196	    lastRenderedLines = lines.length;
197	  }
198	
199	  function triggerSearch(q: string): void {
200	    // Always clear any pending debounce timer
201	    if (debounceTimer) {
202	      clearTimeout(debounceTimer);
203	      debounceTimer = null;
204	    }
205	
206	    // Always reset loading state when starting a new search
207	    loading = false;
208	
209	    if (!q || q.length < 2) {
210	      results = [];
211	      selectedIndex = 0;
212	      render();
213	      return;
214	    }
215	
216	    // Use API search for all queries (debounced)
217	    loading = true;
218	    render();
219	
220	    // Adaptive debounce: shorter queries = longer wait (user still typing)
221	    // 2 chars: 250ms, 3 chars: 200ms, 4 chars: 150ms, 5+ chars: 150ms
222	    const debounceMs = Math.max(150, 350 - q.length * 50);
223	
224	    debounceTimer = setTimeout(async () => {
225	      try {
226	        results = await searchSkillsAPI(q, owner);
227	        selectedIndex = 0;
228	      } catch {
229	        results = [];
230	      } finally {
231	        loading = false;
232	        debounceTimer = null;
233	        render();
234	      }
235	    }, debounceMs);
236	  }
237	
238	  // Trigger initial search if there's a query, then render
239	  if (initialQuery) {
240	    triggerSearch(initialQuery);
241	  }
242	  render();
243	
244	  return new Promise((resolve) => {
245	    function cleanup(): void {
246	      process.stdin.removeListener('keypress', handleKeypress);
247	      if (process.stdin.isTTY) {
248	        process.stdin.setRawMode(false);
249	      }
250	      process.stdout.write(SHOW_CURSOR);
251	      // Pause stdin to fully release it for child processes
252	      process.stdin.pause();
253	    }
254	
255	    function handleKeypress(_ch: string | undefined, key: readline.Key): void {
256	      if (!key) return;
257	
258	      if (key.name === 'escape' || (key.ctrl && key.name === 'c')) {
259	        // Cancel
260	        cleanup();
261	        resolve(null);
262	        return;
263	      }
264	
265	      if (key.name === 'return') {
266	        // Submit
267	        cleanup();
268	        resolve(results[selectedIndex] || null);
269	        return;
270	      }
271	
272	      if (key.name === 'up') {
273	        selectedIndex = Math.max(0, selectedIndex - 1);
274	        render();
275	        return;
276	      }
277	
278	      if (key.name === 'down') {
279	        selectedIndex = Math.min(Math.max(0, results.length - 1), selectedIndex + 1);
280	        render();
281	        return;
282	      }
283	
284	      if (key.name === 'backspace') {
285	        if (query.length > 0) {
286	          query = query.slice(0, -1);
287	          triggerSearch(query);
288	        }
289	        return;
290	      }
291	
292	      // Regular character input
293	      if (key.sequence && !key.ctrl && !key.meta && key.sequence.length === 1) {
294	        const char = key.sequence;
295	        if (char >= ' ' && char <= '~') {
296	          query += char;
297	          triggerSearch(query);
298	        }
299	      }
300	    }
301	
302	    process.stdin.on('keypress', handleKeypress);
303	  });
304	}
