306	// Parse owner/repo from a package string (for the find command)
307	function getOwnerRepoFromString(pkg: string): { owner: string; repo: string } | null {
308	  // Handle owner/repo or owner/repo@skill
309	  const atIndex = pkg.lastIndexOf('@');
310	  const repoPath = atIndex > 0 ? pkg.slice(0, atIndex) : pkg;
311	  const match = repoPath.match(/^([^/]+)\/([^/]+)$/);
312	  if (match) {
313	    return { owner: match[1]!, repo: match[2]! };
314	  }
315	  return null;
316	}
