318	async function isRepoPublic(owner: string, repo: string): Promise<boolean> {
319	  const isPrivate = await isRepoPrivate(owner, repo);
320	  // Return true only if we know it's public (isPrivate === false)
321	  // Return false if private or unable to determine
322	  return isPrivate === false;
323	}
