325	export async function runFind(args: string[]): Promise<void> {
326	  const { query, options: findOptions, errors } = parseFindOptions(args);
327	  const owner = findOptions.owner;
328	  const isNonInteractive = !process.stdin.isTTY;
329	  const agentTip = `${DIM}Tip: if running in a coding agent, follow these steps:${RESET}
330	${DIM}  1) npx skills find [query] [--owner <owner>]${RESET}
331	${DIM}  2) npx skills add <owner/repo@skill>${RESET}`;
332	
333	  if (errors.length > 0) {
334	    for (const error of errors) console.error(error);
335	    console.error('Usage: npx skills find <query> [--owner <owner>]');
336	    return;
337	  }
338	
339	  // Non-interactive mode: just print results and exit
340	  if (query) {
341	    const results = await searchSkillsAPI(query, owner);
342	
343	    // Track telemetry for non-interactive search
344	    track({
345	      event: 'find',
346	      query,
347	      resultCount: String(results.length),
348	    });
349	
350	    if (results.length === 0) {
351	      const ownerSuffix = owner ? ` from owner "${owner}"` : '';
352	      console.log(`${DIM}No skills found for "${query}"${ownerSuffix}${RESET}`);
353	      return;
354	    }
355	
356	    console.log(`${DIM}Install with${RESET} npx skills add <owner/repo@skill>`);
357	    console.log();
358	
359	    for (const skill of results.slice(0, 6)) {
360	      const pkg = skill.source || skill.slug;
361	      const installs = formatInstalls(skill.installs);
362	      console.log(
363	        `${TEXT}${pkg}@${skill.name}${RESET}${installs ? ` ${CYAN}${installs}${RESET}` : ''}`
364	      );
365	      console.log(`${DIM}└ https://skills.sh/${skill.slug}${RESET}`);
366	      console.log();
367	    }
368	    return;
369	  }
370	
371	  // Skip interactive search when running inside an AI agent or non-TTY
372	  if (isNonInteractive || (await isRunningInAgent())) {
373	    console.log(agentTip);
374	    console.log();
375	    console.log(`${DIM}Usage: npx skills find <query> [--owner <owner>]${RESET}`);
376	    return;
377	  }
378	
379	  const selected = await runSearchPrompt('', owner);
380	
381	  // Track telemetry for interactive search
382	  track({
383	    event: 'find',
384	    query: '',
385	    resultCount: selected ? '1' : '0',
386	    interactive: '1',
387	  });
388	
389	  if (!selected) {
390	    console.log(`${DIM}Search cancelled${RESET}`);
391	    console.log();
392	    return;
393	  }
394	
395	  // Use source (owner/repo) and skill name for installation
396	  const pkg = selected.source || selected.slug;
397	  const skillName = selected.name;
398	
399	  console.log();
400	  console.log(`${TEXT}Installing ${BOLD}${skillName}${RESET} from ${DIM}${pkg}${RESET}…`);
401	  console.log();
402	
403	  // Run add directly since we're in the same CLI
404	  const { source, options: addOptions } = parseAddOptions([pkg, '--skill', skillName]);
405	  await runAdd(source, addOptions);
406	
407	  console.log();
408	
409	  const info = getOwnerRepoFromString(pkg);
410	  if (info && (await isRepoPublic(info.owner, info.repo))) {
411	    console.log(
412	      `${DIM}View the skill at${RESET} ${TEXT}https://skills.sh/${selected.slug}${RESET}`
413	    );
414	  } else {
415	    console.log(`${DIM}Discover more skills at${RESET} ${TEXT}https://skills.sh${RESET}`);
416	  }
417	
418	  console.log();
419	}
