40	function normalizeSkillName(name: string): string {
41	  return name.toLowerCase().replace(/[\s_]+/g, '-');
42	}
43	
44	function normalizeRelativePath(path: string): string {
45	  return path.split(sep).join('/').replace(/\/+/g, '/');
46	}
