52	/**
53	 * Check if internal skills should be installed.
54	 * Internal skills are hidden by default unless INSTALL_INTERNAL_SKILLS=1 is set.
55	 */
56	export function shouldInstallInternalSkills(): boolean {
57	  const envValue = process.env.INSTALL_INTERNAL_SKILLS;
58	  return envValue === '1' || envValue === 'true';
59	}
