61	async function hasSkillMd(dir: string): Promise<boolean> {
62	  try {
63	    const skillPath = join(dir, 'SKILL.md');
64	    const stats = await stat(skillPath);
65	    return stats.isFile();
66	  } catch {
67	    return false;
68	  }
