75	export async function parseSkillMd(
76	  skillMdPath: string,
77	  options?: { includeInternal?: boolean }
78	): Promise<Skill | null> {
79	  let content: string;
80	  try {
81	    content = await readFile(skillMdPath, 'utf-8');
82	  } catch (err) {
83	    warnSkippedSkill(skillMdPath, `failed to read file: ${(err as Error).message}`);
84	    return null;
85	  }
86	
87	  let data: Record<string, unknown>;
88	  try {
89	    ({ data } = parseFrontmatter(content));
90	  } catch (err) {
91	    warnSkippedSkill(skillMdPath, `YAML parse error: ${(err as Error).message}`);
92	    return null;
93	  }
94	
95	  if (!data.name || !data.description) {
96	    const missing: string[] = [];
97	    if (!data.name) missing.push('name');
98	    if (!data.description) missing.push('description');
99	    warnSkippedSkill(skillMdPath, `missing required frontmatter field(s): ${missing.join(', ')}`);
100	    return null;
101	  }
102	
103	  // Ensure name and description are strings (YAML can parse numbers, booleans, etc.)
104	  if (typeof data.name !== 'string' || typeof data.description !== 'string') {
105	    warnSkippedSkill(
106	      skillMdPath,
107	      `frontmatter "name" and "description" must be strings (got ${typeof data.name} and ${typeof data.description})`
108	    );
109	    return null;
110	  }
111	
112	  // Skip internal skills unless:
113	  // 1. INSTALL_INTERNAL_SKILLS=1 is set, OR
114	  // 2. includeInternal option is true (e.g., when user explicitly requests a skill)
115	  const metadata = isRecord(data.metadata) ? data.metadata : undefined;
116	  const isInternal = metadata?.internal === true;
117	  if (isInternal && !shouldInstallInternalSkills() && !options?.includeInternal) {
118	    return null;
119	  }
120	
121	  return {
122	    name: sanitizeMetadata(data.name),
123	    description: sanitizeMetadata(data.description),
124	    path: dirname(skillMdPath),
125	    rawContent: content,
126	    metadata,
127	  };
128	}
