130	async function findSkillDirs(dir: string, depth = 0, maxDepth = 5): Promise<string[]> {
131	  if (depth > maxDepth) return [];
132	
133	  try {
134	    const [hasSkill, entries] = await Promise.all([
135	      hasSkillMd(dir),
136	      readdir(dir, { withFileTypes: true }).catch(() => []),
137	    ]);
138	
139	    const currentDir = hasSkill ? [dir] : [];
140	
141	    // Search subdirectories in parallel
142	    const subDirResults = await Promise.all(
143	      entries
144	        .filter((entry) => entry.isDirectory() && !SKIP_DIRS.includes(entry.name))
145	        .map((entry) => findSkillDirs(join(dir, entry.name), depth + 1, maxDepth))
146	    );
147	
148	    return [...currentDir, ...subDirResults.flat()];
149	  } catch {
150	    return [];
151	  }
152	}
