154	export interface DiscoverSkillsOptions {
155	  /** Include internal skills (e.g., when user explicitly requests a skill by name) */
156	  includeInternal?: boolean;
157	  /** Search all subdirectories even when a root SKILL.md exists */
158	  fullDepth?: boolean;
