161	/**
162	 * Validates that a resolved subpath stays within the base directory.
163	 * Prevents path traversal attacks where subpath contains ".." segments
164	 * that would escape the cloned repository directory.
165	 */
166	export function isSubpathSafe(basePath: string, subpath: string): boolean {
167	  const normalizedBase = normalize(resolve(basePath));
168	  const normalizedTarget = normalize(resolve(join(basePath, subpath)));
169	
170	  return normalizedTarget.startsWith(normalizedBase + sep) || normalizedTarget === normalizedBase;
171	}
