173	export async function discoverSkills(
174	  basePath: string,
175	  subpath?: string,
176	  options?: DiscoverSkillsOptions
177	): Promise<Skill[]> {
178	  const skills: Skill[] = [];
179	  const seenNames = new Set<string>();
180	  const parsedSkillPaths = new Set<string>();
181	  const localLock = await readLocalLock(basePath);
182	  const lockedSkillNames = new Set(Object.keys(localLock.skills).map(normalizeSkillName));
183	
184	  // Validate subpath doesn't escape basePath (prevent path traversal)
185	  if (subpath && !isSubpathSafe(basePath, subpath)) {
186	    throw new Error(
187	      `Invalid subpath: "${subpath}" resolves outside the repository directory. Subpath must not contain ".." segments that escape the base path.`
188	    );
189	  }
190	
191	  const searchPath = subpath ? join(basePath, subpath) : basePath;
192	
193	  // Get plugin groupings to map skills to their parent plugin
194	  // We search for plugin definitions from the base search path
195	  const pluginGroupings = await getPluginGroupings(searchPath);
196	
197	  // Helper to assign plugin name if available
198	  const enhanceSkill = (skill: Skill) => {
199	    const resolvedPath = resolve(skill.path);
200	    if (pluginGroupings.has(resolvedPath)) {
201	      skill.pluginName = pluginGroupings.get(resolvedPath);
202	    }
203	    return skill;
204	  };
205	
206	  const isInstalledProjectSkill = (skill: Skill): boolean => {
207	    if (lockedSkillNames.size === 0) return false;
208	
209	    const relativeDir = normalizeRelativePath(relative(basePath, skill.path));
210	    const isAgentSkillPath = AGENT_PROJECT_SKILL_DIRS.some(
211	      (dir) => relativeDir === dir || relativeDir.startsWith(`${dir}/`)
212	    );
213	    if (!isAgentSkillPath) return false;
214	
215	    const skillName = normalizeSkillName(skill.name);
216	    const directoryName = normalizeSkillName(basename(skill.path));
217	    return lockedSkillNames.has(skillName) || lockedSkillNames.has(directoryName);
218	  };
219	
220	  const parseSkillAt = async (skillDir: string): Promise<Skill | null> => {
221	    const skillMdPath = resolve(skillDir, 'SKILL.md');
222	    if (parsedSkillPaths.has(skillMdPath)) return null;
223	    parsedSkillPaths.add(skillMdPath);
224	    return parseSkillMd(skillMdPath, options);
225	  };
226	
227	  // If pointing directly at a skill, add it (and return early unless fullDepth is set).
228	  // If the root SKILL.md is an installed project skill tracked by skills-lock.json,
229	  // ignore it and continue scanning in case the repo also contains source skills.
230	  if (await hasSkillMd(searchPath)) {
231	    let skill = await parseSkillAt(searchPath);
232	    if (skill) {
233	      if (!isInstalledProjectSkill(skill)) {
234	        skill = enhanceSkill(skill);
235	        skills.push(skill);
236	        seenNames.add(skill.name);
237	        // Only return early if fullDepth is not set
238	        if (!options?.fullDepth) {
239	          return skills;
240	        }
241	      }
242	    }
243	  }
244	
245	  // Search common skill locations first
246	  const prioritySearchDirs = [
247	    searchPath,
248	    join(searchPath, 'skills'),
249	    join(searchPath, 'skills/.curated'),
250	    join(searchPath, 'skills/.experimental'),
251	    join(searchPath, 'skills/.system'),
252	    ...AGENT_PROJECT_SKILL_DIRS.map((dir) => join(searchPath, dir)),
253	  ];
254	
255	  // Known skill container dirs are walked one extra level deep so layouts
256	  // like `skills/<category>/<skill>/SKILL.md` are discovered without
257	  // requiring `--full-depth`. The repo root (first entry) keeps its
258	  // existing depth-1 behavior to avoid surfacing unrelated `SKILL.md`
259	  // files (e.g. `examples/foo/SKILL.md`), and plugin-manifest-declared
260	  // dirs (appended below) stay at depth-1 to honor the manifest spec.
261	  const deepContainerDirs = new Set(prioritySearchDirs.slice(1));
262	
263	  // Add skill paths declared in plugin manifests
264	  prioritySearchDirs.push(...(await getPluginSkillPaths(searchPath)));
265	
266	  const tryAddSkillAt = async (skillDir: string): Promise<boolean> => {
267	    if (!(await hasSkillMd(skillDir))) return false;
268	    let skill = await parseSkillAt(skillDir);
269	    if (!skill || seenNames.has(skill.name)) return true;
270	    if (isInstalledProjectSkill(skill)) return true;
271	    skill = enhanceSkill(skill);
272	    skills.push(skill);
273	    seenNames.add(skill.name);
274	    return true;
275	  };
276	
277	  for (const dir of prioritySearchDirs) {
278	    const walkDeep = deepContainerDirs.has(dir);
279	
280	    try {
281	      const entries = await readdir(dir, { withFileTypes: true });
282	
283	      for (const entry of entries) {
284	        if (!entry.isDirectory()) continue;
285	
286	        const childDir = join(dir, entry.name);
287	        const foundAtChild = await tryAddSkillAt(childDir);
288	
289	        // Don't descend past a discovered SKILL.md (matches the existing
290	        // flat-layout semantics) and don't go deeper inside non-container
291	        // priority dirs.
292	        if (foundAtChild || !walkDeep) continue;
293	        if (SKIP_DIRS.includes(entry.name)) continue;
294	
295	        // Walk one extra level for catalog layouts.
296	        try {
297	          const grandEntries = await readdir(childDir, { withFileTypes: true });
298	          for (const grand of grandEntries) {
299	            if (!grand.isDirectory() || SKIP_DIRS.includes(grand.name)) continue;
300	            await tryAddSkillAt(join(childDir, grand.name));
301	          }
302	        } catch {
303	          // Child dir unreadable; skip silently.
304	        }
305	      }
306	    } catch {
307	      // Directory doesn't exist
308	    }
309	  }
310	
311	  // Fall back to recursive search if nothing found, or if fullDepth is set
312	  if (skills.length === 0 || options?.fullDepth) {
313	    const allSkillDirs = await findSkillDirs(searchPath);
314	
315	    for (const skillDir of allSkillDirs) {
316	      let skill = await parseSkillAt(skillDir);
317	      if (skill && !seenNames.has(skill.name) && !isInstalledProjectSkill(skill)) {
318	        skill = enhanceSkill(skill);
319	        skills.push(skill);
320	        seenNames.add(skill.name);
321	      }
322	    }
323	  }
324	
325	  return skills;
326	}
