44	/**
45	 * Sanitizes a filename/directory name to prevent path traversal attacks
46	 * and ensures it follows kebab-case convention
47	 * @param name - The name to sanitize
48	 * @returns Sanitized name safe for use in file paths
49	 */
50	export function sanitizeName(name: string): string {
51	  const sanitized = name
52	    .toLowerCase()
53	    // Replace any sequence of characters that are NOT lowercase letters (a-z),
54	    // digits (0-9), dots (.), or underscores (_) with a single hyphen.
55	    // This converts spaces, special chars, and path traversal attempts (../) into hyphens.
56	    .replace(/[^a-z0-9._]+/g, '-')
57	    // Remove leading/trailing dots and hyphens to prevent hidden files (.) and
58	    // ensure clean directory names. The pattern matches:
59	    // - ^[.\-]+ : one or more dots or hyphens at the start
60	    // - [.\-]+$ : one or more dots or hyphens at the end
61	    .replace(/^[.\-]+|[.\-]+$/g, '');
62	
63	  // Limit to 255 chars (common filesystem limit), fallback to 'unnamed-skill' if empty
64	  return sanitized.substring(0, 255) || 'unnamed-skill';
65	}
