402	  // First check for @skill syntax: owner/repo@skill-name
403	  const atSkillMatch = input.match(/^([^/]+)\/([^/@]+)@(.+)$/);
404	  if (atSkillMatch && !input.includes(':') && !input.startsWith('.') && !input.startsWith('/')) {
405	    const [, owner, repo, skillFilter] = atSkillMatch;
406	    return {
407	      type: shorthandSourceType,
408	      url: `https://${githubHost}/${owner}/${repo}.git`,
409	      ...(fragmentRef ? { ref: fragmentRef } : {}),
410	      skillFilter: fragmentSkillFilter || skillFilter,
411	    };
412	  }
413	
414	  const shorthandMatch = input.match(/^([^/]+)\/([^/]+)(?:\/(.+?))?\/?$/);
415	  if (shorthandMatch && !input.includes(':') && !input.startsWith('.') && !input.startsWith('/')) {
416	    const [, owner, repo, subpath] = shorthandMatch;
417	    return {
418	      type: shorthandSourceType,
