460	      return false;
461	    }
462	
463	    // Don't match URLs that look like git repos (should be handled by git type)
464	    if (input.endsWith('.git')) {
465	      return false;
466	    }
467	
468	    return true;
469	  } catch {
470	    return false;
471	  }
